=== END FILE ===
=== FILE: rr_arbiter_props.sv ===
// Formal property set for rr_arbiter (interface_spec.md, rules RR-*).
// Immediate assertions only, inside always blocks, for the open Yosys front end.
// No assumptions: clk, rst_n and req are left free.
module rr_arbiter_props (
    input wire       clk,
    input wire       rst_n,
    input wire [2:0] req
);
    wire [2:0] grant;
    wire [1:0] last;

    rr_arbiter dut (
        .clk   (clk),
        .rst_n (rst_n),
        .req   (req),
        .grant (grant),
        .last  (last)
    );

    // ------------------------------------------------------------------
    // Bookkeeping: first-cycle guard for $past, and "a reset has been seen"
    // ------------------------------------------------------------------
    reg f_past_valid = 1'b0;
    reg f_reset_done = 1'b0;
    always @(posedge clk) begin
        f_past_valid <= 1'b1;
        if (!rst_n)
            f_reset_done <= 1'b1;
    end

    // Priority order from the spec: last+1, last+2, last (mod 3)
    wire [1:0] f_n1 = (last == 2'd2) ? 2'd0 : (last + 2'd1);
    wire [1:0] f_n2 = (last == 2'd0) ? 2'd2 : (last - 2'd1);

    // ------------------------------------------------------------------
    // Wait counters for RR-BOUND: consecutive non-reset edges at which
    // requester i held req[i] high and was not granted.
    // ------------------------------------------------------------------
    reg [1:0] f_wait0 = 2'd0;
    reg [1:0] f_wait1 = 2'd0;
    reg [1:0] f_wait2 = 2'd0;
    always @(posedge clk) begin
        if (!rst_n || !f_reset_done || !req[0] || grant[0])
            f_wait0 <= 2'd0;
        else if (f_wait0 != 2'd3)
            f_wait0 <= f_wait0 + 2'd1;

        if (!rst_n || !f_reset_done || !req[1] || grant[1])
            f_wait1 <= 2'd0;
        else if (f_wait1 != 2'd3)
            f_wait1 <= f_wait1 + 2'd1;

        if (!rst_n || !f_reset_done || !req[2] || grant[2])
            f_wait2 <= 2'd0;
        else if (f_wait2 != 2'd3)
            f_wait2 <= f_wait2 + 2'd1;
    end

    // ------------------------------------------------------------------
    // Combinational properties of grant (checked every step)
    // ------------------------------------------------------------------
    always @(*) begin
        // [req:RR-IDLE] no request, no grant
        if (req == 3'b000)
            assert (grant == 3'b000);

        // [req:RR-ONLY-REQUESTERS] never grant a requester that is not requesting
        assert ((grant & ~req) == 3'b000);

        // [req:RR-PICK] exactly one grant when any request is present
        if (req != 3'b000)
            assert ((grant != 3'b000) && ((grant & (grant - 3'b001)) == 3'b000));

        // [req:RR-PICK] the grant is the first requester in rotation order
        if (f_reset_done) begin
            if (req[f_n1])
                assert (grant == (3'b001 << f_n1));
            else if (req[f_n2])
                assert (grant == (3'b001 << f_n2));
            else if (req[last])
                assert (grant == (3'b001 << last));
        end

        // [req:RR-BOUND] a held request is granted by its third edge
        if (f_reset_done && req[0] && (f_wait0 == 2'd2))
            assert (grant[0]);
        if (f_reset_done && req[1] && (f_wait1 == 2'd2))
            assert (grant[1]);
        if (f_reset_done && req[2] && (f_wait2 == 2'd2))
            assert (grant[2]);

        // Helper invariants (describe the reachable state for induction)
        if (f_reset_done)
            assert (last != 2'd3);
        if (f_reset_done)
            assert (f_past_valid);
        if (!f_reset_done)
            assert ((f_wait0 == 2'd0) && (f_wait1 == 2'd0) && (f_wait2 == 2'd0));
        assert (f_wait0 <= 2'd2);
        assert (f_wait1 <= 2'd2);
        assert (f_wait2 <= 2'd2);
    end

    // ------------------------------------------------------------------
    // Sequential properties of last (checked at clock edges)
    // ------------------------------------------------------------------
    always @(posedge clk) begin
        // [req:RR-RESET] reset loads last = 2
        if (f_past_valid && !$past(rst_n))
            assert (last == 2'd2);

        // [req:RR-ROTATE] the granted requester becomes last
        if (f_past_valid && $past(rst_n) && ($past(grant) != 3'b000))
            assert ((3'b001 << last) == $past(grant));

        // [req:RR-HOLD] no grant, last unchanged
        if (f_past_valid && $past(rst_n) && ($past(grant) == 3'b000))
            assert (last == $past(last));

        // [req:RR-YIELD] the previous grantee yields to any other requester
        if (f_past_valid && $past(rst_n) && ($past(grant) != 3'b000)
            && ((req & ~$past(grant)) != 3'b000))
            assert ((grant & $past(grant)) == 3'b000);
    end

    // ------------------------------------------------------------------
    // Covers: scenarios the proof must still allow
    // ------------------------------------------------------------------
    always @(posedge clk) begin
        cover (f_reset_done && (grant == 3'b001));
        cover (f_reset_done && (grant == 3'b010));
        cover (f_reset_done && (grant == 3'b100));
        cover (f_reset_done && (req == 3'b111));
        // each requester reaches its worst-case wait and is then granted
        cover (f_reset_done && (f_wait0 == 2'd2) && grant[0]);
        cover (f_reset_done && (f_wait1 == 2'd2) && grant[1]);
        cover (f_reset_done && (f_wait2 == 2'd2) && grant[2]);
        // yield after a grant, with another requester waiting
        if (f_past_valid)
            cover ($past(f_reset_done) && $past(rst_n) && ($past(grant) != 3'b000)
                   && ((req & ~$past(grant)) != 3'b000) && (req & $past(grant)) != 3'b000);
        // hold: idle edge after reset
        if (f_past_valid)
            cover ($past(f_reset_done) && $past(rst_n) && ($past(grant) == 3'b000));
    end
endmodule
=== END FILE ===
